        rank = 0
        for assignment in assignments:
            max_value = -math.inf
            for node, neighbors in G.items():
                value = sum(assignment[node] if i == node else 0 for i in neighbors)
                max_value = max(max_value, value)
            rank = max(rank, max_value)
        return rank

